34	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
35	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
36	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
37	    @Mapping(target = "locality", expression = "java(locality(owner))")
